import { getAccessToken, getRefreshToken, setTokens } from '../auth/preferencesStore'

const API_BASE = import.meta.env.VITE_API_BASE_URL as string

export class ApiError extends Error {
  status: number
  constructor(status: number, message: string) {
    super(message)
    this.status = status
  }
}

async function doFetch(path: string, options: RequestInit, accessToken: string | null): Promise<Response> {
  const headers = new Headers(options.headers)
  if (accessToken) headers.set('Authorization', `Bearer ${accessToken}`)
  if (options.body && !headers.has('Content-Type')) headers.set('Content-Type', 'application/json')
  return fetch(`${API_BASE}${path}`, { ...options, headers })
}

async function refreshAccessToken(): Promise<string> {
  const refreshToken = await getRefreshToken()
  if (!refreshToken) throw new ApiError(401, 'no refresh token available')

  const response = await fetch(`${API_BASE}/api/v1/auth/refresh`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ refresh_token: refreshToken }),
  })
  if (!response.ok) {
    await setTokens(null, null)
    throw new ApiError(401, 'refresh failed')
  }
  const tokens = await response.json()
  await setTokens(tokens.access_token, tokens.refresh_token)
  return tokens.access_token
}

export async function apiFetch<T>(path: string, options: RequestInit = {}): Promise<T> {
  let response = await doFetch(path, options, getAccessToken())

  if (response.status === 401) {
    const newAccessToken = await refreshAccessToken()
    response = await doFetch(path, options, newAccessToken)
  }

  if (!response.ok) {
    throw new ApiError(response.status, `request to ${path} failed with ${response.status}`)
  }

  if (response.status === 204) return undefined as T
  return response.json()
}

import { describe, it, expect, vi, beforeEach } from 'vitest'

// preferencesStore's async half (refresh token) goes through the real
// @capacitor/preferences plugin, which needs a native bridge or a browser
// `window.localStorage` to back it. Neither exists under vitest's default
// node environment, so fake the plugin with a plain in-memory map -- this
// test is exercising apiFetch's retry logic, not Capacitor's storage plugin.
// Plain functions (not vi.fn) so vi.restoreAllMocks() in beforeEach can't
// strip their implementation out from under the test.
const fakePreferences = new Map<string, string>()
vi.mock('@capacitor/preferences', () => ({
  Preferences: {
    get: async ({ key }: { key: string }) => ({ value: fakePreferences.get(key) ?? null }),
    set: async ({ key, value }: { key: string; value: string }) => {
      fakePreferences.set(key, value)
    },
    remove: async ({ key }: { key: string }) => {
      fakePreferences.delete(key)
    },
  },
}))

import { setAccessToken, setRefreshToken } from '../auth/preferencesStore'

describe('apiFetch 401 handling', () => {
  beforeEach(async () => {
    setAccessToken('old-access-token')
    await setRefreshToken('a-refresh-token')
    vi.restoreAllMocks()
  })

  it('refreshes once and retries once on a 401, then succeeds', async () => {
    const responses = [
      new Response(null, { status: 401 }),
      new Response(JSON.stringify({ access_token: 'new-access-token', refresh_token: 'new-refresh-token' }), { status: 200 }),
      new Response(JSON.stringify({ ok: true }), { status: 200 }),
    ]
    const fetchMock = vi.fn().mockImplementation(() => Promise.resolve(responses.shift()!))
    vi.stubGlobal('fetch', fetchMock)

    const { apiFetch } = await import('./client')
    const result = await apiFetch<{ ok: boolean }>('/api/v1/zones')

    expect(result).toEqual({ ok: true })
    expect(fetchMock).toHaveBeenCalledTimes(3)
    // second call must be the refresh endpoint
    expect(fetchMock.mock.calls[1][0]).toContain('/api/v1/auth/refresh')
  })

  it('does not loop -- a second consecutive 401 after refresh throws instead of retrying again', async () => {
    const responses = [
      new Response(null, { status: 401 }),
      new Response(JSON.stringify({ access_token: 'new-access-token', refresh_token: 'new-refresh-token' }), { status: 200 }),
      new Response(null, { status: 401 }),
    ]
    const fetchMock = vi.fn().mockImplementation(() => Promise.resolve(responses.shift()!))
    vi.stubGlobal('fetch', fetchMock)

    const { apiFetch } = await import('./client')

    await expect(apiFetch('/api/v1/zones')).rejects.toThrow()
    expect(fetchMock).toHaveBeenCalledTimes(3)
  })

  it('when the refresh call itself fails, clears tokens and throws without retrying the original request', async () => {
    const responses = [
      new Response(null, { status: 401 }),
      new Response(null, { status: 401 }), // refresh itself fails
    ]
    const fetchMock = vi.fn().mockImplementation(() => Promise.resolve(responses.shift()!))
    vi.stubGlobal('fetch', fetchMock)

    const { apiFetch } = await import('./client')
    const { getAccessToken } = await import('../auth/preferencesStore')

    await expect(apiFetch('/api/v1/zones')).rejects.toThrow()
    expect(fetchMock).toHaveBeenCalledTimes(2)
    expect(getAccessToken()).toBeNull()
  })
})

