  id: string
  rep_id: string
  zone_id: string | null
  checked_in_at: string
  checked_out_at: string | null
  latitude: number
  longitude: number
  geofence_verified: boolean
  notes: string | null
  external_reference: string | null
}

// Matches TaskOut (backend/app/tasks/schemas.py)
export interface Task {
  id: string
  assigned_to: string
  title: string
  due_date: string | null
  status: string
  priority: string
  external_reference: string | null
  created_at: string
  completed_at: string | null
}

// Matches GoalOut (backend/app/goals/schemas.py)
export interface Goal {
  id: string
  rep_id: string
  metric_type: string
  target: number
  period_start: string
  period_end: string
  manual_value: number | null
  created_at: string
}

// Matches GoalProgress (backend/app/goals/schemas.py)
export interface GoalProgress {
  goal_id: string
  rep_id: string
  metric_type: string
  target: number
  achieved: number
  period_start: string
  period_end: string
}

